"""Explain add-unless, bounded integer arithmetic, aliases and atomic-long selection."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1545': ('“숫자판이 0일 때에는 더하지 말고, 그 밖의 값이면 2를 더해 주세요”라는 규칙을 생각해 봅시다. 담당자는 일을 했는지와 별개로 처음 본 숫자를 알려 줍니다.', '금지 값 비교와 갱신 전 반환값을 구별합니다.', '이전 0·더할 값 2·금지 값 0이면 반환 0·저장 0, 이전 5이면 반환 5·저장 7을 적으세요.', ['generic_atomic64_fetch_add_unless는 조건에 따라 더하는 함수입니다. a는 더할 수, u는 이 값일 때 더하지 말라는 금지 값입니다. unless는 “그 경우가 아니라면”이라는 뜻입니다.', '잠금을 잡은 뒤 원본 counter를 val에 복사합니다. 다음 if (val != u)에서 이전 값과 금지 값이 다른지 봅니다. 다를 때에만 counter += a를 실행합니다. 비교와 갱신은 같은 보호 구간에 있습니다.', '이전 값 5, a=2, u=0이면 서로 다르므로 저장값은 7이 됩니다. 반환은 처음 복사한 5입니다. 성공을 뜻하는 숫자 1을 만들어 돌려주는 함수가 아닙니다.', '이전 값이 금지 값 0과 같으면 더하지 않습니다. 저장값과 반환값 모두 0입니다. 일반적으로 실행 여부는 반환값이 u와 다른지를 비교해 판단합니다. 단순히 반환값이 0인지로 모든 경우를 판단하지 마세요.', '금지 값은 딱 한 값을 비교하는 조건입니다. 예를 들어 u=5이고 원본이 0이면 0도 더할 수 있는 값입니다. 성공하면서 이전 값 0을 반환할 수 있으므로 bool처럼 읽으면 틀립니다.', '이 코드는 모든 음수나 범위 초과, 자료가 이미 없어졌는지를 검사하지 않습니다. 또한 결과가 u가 되는 덧셈까지 금지하는 규칙도 아닙니다. 시작 값이 u인지 검사할 뿐이므로 입력 범위와 자료 수명은 호출자가 따로 지켜야 합니다.'], [('현재 5에서 a=2, u=0으로 fetch_add_unless를 하면?', ['반환 1, 저장 7이에요', '반환 5, 저장 7이에요'], '5는 금지 값 0과 달라서 2를 더합니다. 반환은 이전 값 5예요. 갱신했는지는 반환값이 금지 값과 다른지 확인해야 합니다.'), ('현재 값이 u와 같다면 무엇을 하나요?', ['바꾸지 않고 이전 값을 돌려줘요', '무조건 금지 값 u를 0으로 바꿔요'], '본문은 val != u일 때만 더합니다. 금지 값 자체를 수정하거나 원본을 0으로 초기화하는 명령은 없어요.')]), 'os1546': ('끝이 정해진 숫자판에서는 마지막 다음에 다시 처음으로 돌아가는 규칙을 쓸 수 있습니다. 하지만 어떤 숫자판은 다른 규칙을 쓰므로 먼저 계산 규칙을 확인해야 합니다.', '정수 범위 끝의 wrap과 조건 검사 위치를 구별합니다.', '64비트 최대값+1 → 최소값, 최소값-1 → 최대값의 두 화살표를 그리세요. 이 수업은 wrap을 정한 구성의 예시라고 적으세요.', ['s64는 부호 있는 64비트 정수입니다. 표현 가능한 수는 -9223372036854775808부터 9223372036854775807까지입니다. 컴퓨터 정수 칸은 무한히 큰 수를 담는 수학의 정수와 다릅니다.', 'wrap은 범위 끝을 넘어가면 비트 폭에 맞춰 반대쪽 값으로 돌아가는 계산 방식입니다. GNU C의 -fwrapv를 명시한 구성에서는 최대값 INT64_MAX에 1을 더하면 최소값 INT64_MIN이 됩니다. 최대값에 멈추는 포화 계산과 다릅니다.', '커널 Makefile에는 -fno-strict-overflow 옵션이 있습니다. 실제 코드를 해석할 때에는 이런 빌드 규칙도 봐야 합니다. 일반 C 프로그램에 같은 옵션이나 규약이 없는데 signed overflow도 무조건 같은 결과라고 주장하면 안 됩니다.', 'dec_if_positive의 코드는 원래 값이 양수인지 먼저 검사하지 않습니다. counter-1을 계산한 val이 0 이상인지를 검사합니다. 보통 작은 자원 수에서는 자연스럽지만 표현 범위 끝에서는 이 차이가 중요합니다.', 'wrap 구성에서 원래 값이 INT64_MIN이면 1을 뺀 계산 결과는 INT64_MAX입니다. 이 값은 0 이상이어서 저장되고 반환됩니다. 이름만 보고 “입력이 음수면 전부 거부한다”고 외우면 이 경계를 설명할 수 없습니다.', '이 예시는 극단 입력에서 계산과 조건을 읽는 연습입니다. 실제 자원 수를 이렇게 설정하라는 뜻은 아닙니다. 원자 산술의 wrap은 참조 수 관리의 포화나 자료 수명 보호를 대신하지 않습니다. 이번 설명의 수치 계산과 실제 커널 실행 검증도 구별해야 합니다.'], [('GNU -fwrapv로 64비트 signed wrap을 정한 구성에서 INT64_MAX+1은?', ['언제나 최대값에 멈추며 모든 C 환경도 같아요', 'INT64_MIN으로 돌아가요'], '선택한 wrap 규칙에서는 최대값 다음이 최소값입니다. 최대값에 멈추려면 별도의 포화 규칙이 필요해요. 이 결과를 옵션 없는 모든 C 프로그램으로 넓혀 말하면 안 됩니다.'), ('같은 구성에서 INT64_MIN의 dec_if_positive는 입력이 음수라서 무조건 거부할까요?', ['아니요. 계산 결과 INT64_MAX가 0 이상이라 저장돼요', '네. 코드가 원래 값이 음수인지 먼저 검사해요'], '먼저 counter-1을 계산합니다. wrap 결과가 최대값이면 val >= 0 조건을 통과해요. 검사 대상은 원래 counter가 아니라 계산한 val입니다.')]), 'os1547': ('가게에는 주문 방법을 적은 메뉴, 실제 조리법, 다른 이름으로 같은 메뉴를 찾게 하는 안내가 있습니다. 코드의 선언, 정의, 이름 연결도 역할이 다릅니다.', '함수 선언과 본체 생성, 별칭 연결을 구별합니다.', '헤더 선언 → C 파일 본체 → 실제 실행을 그리고, arch 이름 → generic 이름의 별도 화살표를 그리세요.', ['include/asm-generic/atomic64.h의 ATOMIC64_OP는 extern 함수 선언을 만듭니다. 선언은 이름과 입력·결과 형식을 알려 줍니다. 끝이 세미콜론인 이 줄만으로 실제 잠금과 계산 순서를 모두 실행하는 것은 아닙니다.', '##는 이름 토큰을 붙이는 전처리 기호입니다. op가 add이면 generic_atomic64_add라는 이름을 만듭니다. 완성된 함수 이름이 소스에 그대로 적혀 있지 않아도 매크로를 펼치면 선언이 생길 수 있습니다.', 'lib/atomic64.c의 생성 매크로는 함수 본체까지 만듭니다. 잠금을 잡고 계산하고 푸는 명령은 이쪽에 있습니다. 같은 이름의 매크로라도 헤더에서는 선언을, C 파일에서는 정의를 만드는지 실제 내용을 읽으세요.', '헤더는 필요한 선언을 만든 뒤 #undef로 내부 생성 매크로들을 정리합니다. 앞서 만들어진 선언을 지우는 것이 아니라 이후 코드에서 그 매크로 정의가 계속 적용되지 않게 하는 것입니다.', '마지막 #define arch_atomic64_fetch_add generic_atomic64_fetch_add는 이름 연결입니다. alias, 즉 별칭이라고 부릅니다. 상위 코드의 arch 이름이 이 generic 함수 이름으로 이어집니다. 별칭 자체는 새 counter나 새 연산 본체를 만들지 않습니다.', '실제 객체는 호출할 때 인자로 전달됩니다. 따라서 이름 연결을 찾고, 그 이름의 선언과 생성된 본체를 찾아야 실행 흐름을 이해할 수 있습니다. 내부 생성 매크로를 일반 사용자 API처럼 직접 부르는 방식과 구별하세요.'], [('헤더의 extern 매크로를 펼치면 무엇이 나오나요?', ['잠금 배열과 함수 본체 전체가 나와요', '함수 이름과 입출력 형식을 알리는 선언이 나와요'], '헤더의 해당 양식은 extern ...;입니다. 실제 잠금과 계산 명령을 가진 정의는 C 파일의 양식에서 만들어져요. 선언과 실행 코드를 구별하세요.'), ('arch_atomic64_fetch_add 별칭은 호출마다 새 counter를 만들까요?', ['아니요. 사용할 generic 함수 이름을 연결해요', '네. #define이 새 저장 객체를 만들어 줘요'], '이 별칭은 이름을 바꾸는 규칙입니다. 자료는 호출 인자로 받은 객체를 사용해요. 이름 연결과 객체 생성은 다른 일입니다.')]), 'os1548': ('같은 이름의 상자라도 어느 설계도를 선택했는지에 따라 담을 수 있는 숫자 범위가 달라질 수 있습니다. long이라는 이름만 보고 언제나 64비트 상자라고 생각하면 안 됩니다.', '커널 설정에 따른 atomic_long 자료형과 검증 범위를 이해합니다.', 'CONFIG_64BIT 있음 → atomic64_t, 없음 → atomic_t의 두 갈래를 그리세요. 선언을 읽는 것과 각 환경에서 실행하는 것은 별도라고 적으세요.', ['atomic_long_t는 커널의 long 폭에 맞는 원자 연산을 제공하기 위한 형식입니다. typedef는 기존 자료형에 다른 이름을 붙이는 C 문법입니다. 이름을 붙였다고 별도의 저장 자료형이 항상 새로 생기는 것은 아닙니다.', 'CONFIG_64BIT가 정의된 분기에서는 typedef atomic64_t atomic_long_t가 적용됩니다. 그렇지 않은 #else 분기에서는 atomic_t를 사용합니다. 소스를 번역할 때 설정에 맞는 분기가 선택됩니다.', 'ATOMIC_LONG_INIT도 함께 바뀝니다. 64비트 분기에서는 ATOMIC64_INIT, 다른 분기에서는 ATOMIC_INIT으로 연결됩니다. 조건을 읽는 acquire·relaxed 이름들도 대응하는 계열을 따라갑니다. 초기화와 연산이 같은 선택을 따르는지 확인해야 합니다.', 'raw_atomic_long_try_cmpxchg의 old는 이전 값을 주고받는 long 포인터입니다. 이 wrapper는 64비트 분기에서 s64 포인터로, 다른 분기에서 int 포인터로 연결합니다. 포인터는 자료 위치를 담으므로 자료형의 크기와 호출 규칙을 맞춰야 합니다.', '사용자 공간 Windows 등의 long 규칙을 그대로 가져와 커널 자료형을 판단하지 마세요. 지금 읽는 커널 설정과 헤더의 분기가 기준입니다. 이름에 long이 있다는 사실만으로 모든 환경에서 범위가 같다는 보장은 없습니다.', '64비트 구성에서 실행에 성공했다고 32비트 구성의 ABI까지 실행 검증한 것은 아닙니다. ABI는 자료 크기와 함수 호출 등 기계 코드 사이의 약속입니다. 두 분기를 읽어 확인하는 일과 각 구성을 빌드해 실제 실행하는 일은 서로 다른 증거입니다. 이 수업은 원문의 선택 규칙을 따라 읽습니다.'], [('CONFIG_64BIT가 정의되지 않은 분기에서 atomic_long_t는 무엇인가요?', ['항상 atomic64_t예요', 'atomic_t예요'], '#else 아래 typedef atomic_t atomic_long_t가 있습니다. long이라는 이름으로 추측하지 말고 적용되는 분기를 읽으세요.'), ('64비트 구성에서 실행한 결과만으로 32비트 ABI도 실행 검증했다고 말할 수 있나요?', ['아니요. 32비트 구성은 별도의 빌드·실행 확인이 필요해요', '네. 64비트 CPU에서 실행하면 모든 32비트 ABI도 자동 검증돼요'], '소스의 다른 분기를 읽는 것과 그 분기를 사용하는 실제 실행은 다릅니다. 실행하지 않은 구성까지 검증했다고 확대할 수 없어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_382.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
